diff --git a/src/transport/ws/validation.ts b/src/transport/ws/validation.ts
index 302e325..b12ba53 100644
--- a/src/transport/ws/validation.ts
+++ b/src/transport/ws/validation.ts
@@ -15,6 +15,13 @@ interface ValidationFailure {

 export type ValidationResult = ValidationSuccess | ValidationFailure;

+// One validator per frame type; a type absent here is unknown.
+const VALIDATORS: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
+  user_message: validateUserMessage,
+  ping: validatePingMessage,
+  list_sessions: validateListSessionsMessage,
+};
+
 export function validateMessage(payload: unknown): ValidationResult {
   if (typeof payload !== 'object' || payload === null) {
     return {valid: false, error: 'Message must be an object'};
@@ -26,16 +33,9 @@ export function validateMessage(payload: unknown): ValidationResult {
     return {valid: false, error: 'Message must have a type field'};
   }

-  switch (message.type) {
-    case 'user_message':
-      return validateUserMessage(message);
-    case 'ping':
-      return validatePingMessage(message);
-    case 'list_sessions':
-      return validateListSessionsMessage(message);
-    default:
-      return {valid: false, error: `Unknown message type: ${message.type}`};
-  }
+  const validate = Object.hasOwn(VALIDATORS, message.type) ? VALIDATORS[message.type] : undefined;
+  if (validate === undefined) return {valid: false, error: `Unknown message type: ${message.type}`};
+  return validate(message);
 }

 function validateUserMessage(message: Record<string, unknown>): ValidationResult {
@@ -83,12 +83,12 @@ function validateListSessionsMessage(message: Record<string, unknown>): Validati
   if (limit !== undefined && !(typeof limit === 'number' && Number.isInteger(limit) && limit >= 0)) {
     return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
   }
-  const data: ListSessionsMessage = {type: 'list_sessions', ...(limit === undefined ? {} : {limit})};
-  if (before === undefined) return {valid: true, data};
+  const listRequest: ListSessionsMessage = {type: 'list_sessions', ...(limit === undefined ? {} : {limit})};
+  if (before === undefined) return {valid: true, data: listRequest};

   const cursor = validateCursor(before);
   if (typeof cursor === 'string') return {valid: false, error: cursor};
-  return {valid: true, data: {...data, before: cursor}};
+  return {valid: true, data: {...listRequest, before: cursor}};
 }

 // The cursor a client sends back: the last row it saw, after JSON, so a string or an epoch number.
